# Control: "Enforce multi-factor authentication for all privileged accounts"

mapping = {
    "control": "Enforce MFA for privileged accounts",
    "nist_csf": {
        "function": "Protect",
        "category": "PR.AC-7",
        "description": "Passwords, tokens, and MFA for privileged access"
    },
    "iso_27001": {
        "control": "A.9.4.2",
        "description": "Secure log-on procedures"
    },
    "cis_controls": {
        "control": "5.3",
        "description": "MFA for all administrative access"
    },
    "cobiT": {
        "process": "APO13.02",
        "description": "Manage security controls for user authentication"
    }
}

print("One control maps to four frameworks.")
print(f"NIST CSF: {mapping['nist_csf']['function']} / {mapping['nist_csf']['category']}")
print(f"ISO 27001: Control {mapping['iso_27001']['control']}")
print(f"CIS v8: Control {mapping['cis_controls']['control']}")
print(f"COBIT: Process {mapping['cobiT']['process']}")
